sql.where:
q.status != 'ARCHIVE'


    AND q.user_id = #{query.creatorId}


    AND q.user_id IN (SELECT u.id FROM users u JOIN users_roles ur ON u.id = ur.user_id JOIN roles r ON ur.role_id = r.id WHERE r.role_name IN ('ADMIN', 'CONTENT_MANAGER'))


    AND q.user_id NOT IN (SELECT u.id FROM users u JOIN users_roles ur ON u.id = ur.user_id JOIN roles r ON ur.role_id = r.id WHERE r.role_name IN ('ADMIN', 'CONTENT_MANAGER'))


    AND q.status IN

        #{item}



    AND (
    LOWER(q.title) LIKE CONCAT('%', LOWER(#{query.keyword}), '%')
    OR LOWER(q.description) LIKE CONCAT('%', LOWER(#{query.keyword}), '%')
    )

mapper.select:
SELECT

FROM speaking_questions q



        ORDER BY q.${query.sortBy}

            ${query.sortDirection}


            ASC



        ORDER BY q.created_time DESC


LIMIT #{limit} OFFSET #{offset}
